'use strict';
(()=>{
 const $=id=>document.getElementById(id),id=new URLSearchParams(location.search).get('id'),history=[],form=$('chat-form'),input=$('message'),messages=$('messages'),theme=$('theme');let busy=false;
 const botIcon="<svg viewBox=\"0 0 24 24\" width=\"20\" height=\"20\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><rect x=\"4\" y=\"7\" width=\"16\" height=\"13\" rx=\"4\"/><path d=\"M12 7V3M2 12v4M22 12v4M9 16h6\"/><circle cx=\"9\" cy=\"12\" r=\".7\"/><circle cx=\"15\" cy=\"12\" r=\".7\"/></svg>",userIcon="<svg viewBox=\"0 0 24 24\" width=\"20\" height=\"20\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"8\" r=\"3\"/><path d=\"M5 20c0-4 3-6 7-6s7 2 7 6\"/></svg>";
 function setTheme(value,persist=false){const dark=value==='dark';document.documentElement.dataset.theme=dark?'dark':'light';theme.setAttribute('aria-label',dark?'Switch to light mode':'Switch to dark mode');theme.setAttribute('aria-pressed',String(dark));document.querySelector('meta[name="theme-color"]').content=dark?'#101010':'#f6f5f2';if(persist)try{localStorage.setItem('bf-chat-theme',dark?'dark':'light');}catch{}}
 let initialTheme='light';try{initialTheme=localStorage.getItem('bf-chat-theme')||localStorage.getItem('jh-theme')||(window.matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light');}catch{}setTheme(initialTheme);
 theme.onclick=()=>setTheme(document.documentElement.dataset.theme==='dark'?'light':'dark',true);
 function scrollBottom(){messages.scrollTop=messages.scrollHeight;}
 function messageRow(role){const row=document.createElement('div');row.className='bf-message-row '+role;const avatar=document.createElement('span');avatar.className='bf-chat-avatar';avatar.setAttribute('aria-hidden','true');avatar.innerHTML=role==='assistant'?botIcon:userIcon;const p=document.createElement('div');p.className='bubble '+role;row.append(avatar,p);return {row,p};}
 function bubble(role,text){const {row,p}=messageRow(role);p.textContent=text;messages.append(row);scrollBottom();return row;}
 function typing(){const {row,p}=messageRow('assistant');row.classList.add('bf-typing');row.setAttribute('aria-hidden','true');for(let i=0;i<3;i++)p.append(document.createElement('i'));messages.append(row);scrollBottom();return row;}
 function status(text,error=false){$('chat-status').textContent=text;$('chat-status').classList.toggle('error',error);}
 function resizeInput(){input.style.height='auto';input.style.height=Math.min(120,input.scrollHeight)+'px';}
 function setBusy(value){busy=value;form.querySelector('button').disabled=value;input.disabled=value;for(const b of $('suggestions').querySelectorAll('button'))b.disabled=value;form.setAttribute('aria-busy',String(value));}
 async function api(action,body){const r=await fetch('/api/secretj-botfolio?action='+action,{credentials:'omit',cache:'no-store',...(body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{})});let d;try{d=await r.json();}catch{throw Error('Service unavailable.');}if(!r.ok||!d.ok)throw Error(d.error||'Request failed.');return d;}
 async function send(message){if(busy||!message.trim()||message.length>900)return;setBusy(true);const prior=history.slice(-6),userRow=bubble('user',message),indicator=typing();status('Thinking…');input.value='';resizeInput();try{const r=await api('chat',{id,message,history:prior});indicator.remove();bubble('assistant',r.answer);history.push({role:'user',content:message},{role:'assistant',content:r.answer});if(history.length>6)history.splice(0,history.length-6);status('');}catch(e){indicator.remove();userRow.remove();status(e.message,true);input.value=message;resizeInput();}finally{setBusy(false);if(window.matchMedia('(pointer:fine)').matches)input.focus({preventScroll:true});scrollBottom();}}
 form.onsubmit=e=>{e.preventDefault();send(input.value.trim());};
 input.addEventListener('input',resizeInput);
 input.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing&&window.matchMedia('(pointer:fine)').matches){e.preventDefault();form.requestSubmit();}});
 $('suggestions').onclick=e=>{const button=e.target.closest('button');if(button)send(button.textContent.trim());};
 (async()=>{try{if(!id)throw Error('Missing portfolio link.');const r=await api('public&id='+encodeURIComponent(id));$('name').textContent=r.bot.name;$('headline').textContent=r.bot.headline;document.title=r.bot.name+' · Botfolio';bubble('assistant','Hi! I am the AI portfolio assistant for '+r.bot.name+'. Ask me about the published skills, experience or projects.');form.hidden=false;$('suggestions').hidden=false;resizeInput();scrollBottom();}catch(e){$('name').textContent='Portfolio unavailable';status(e.message,true);}})();
})();
